class Solution:
    def semiOrderedPermutation(self, nums: List[int]) -> int:
        n = len(nums)

        # Check if the permutation is already not semi-ordered
        if nums[0] != 1 or nums[-1] != n:
            return 0

        operations = 0
        i = 0

        while i < n - 1 and nums[i] == i + 1:
            # Find the first pair of adjacent elements that are not in order
            j = i + 1

            while j < n and nums[j] == j + 1:
                j += 1

            if j >= n or nums[j] != j + 1:
                break

            operations += (j - i) // 2
            i = j

        return operations
